/**
 * Create a typed Monospace client for this schema.
 *
 * @example
 * ```ts
 * import { createClient } from './generated/monospace';
 *
 * const client = createClient({
 *   url: 'https://api.example.com',
 *   project: 'my-project',
 *   apiKey: process.env.API_KEY,
 * });
 *
 * const users = await client.User.readMany({
 *   fields: ['id', 'name', 'email'],
 * });
 * ```
 */
export function createClient<
	SN extends boolean = true,
	UE extends boolean = true,
>(
	config: ClientConfig & { strictNull?: SN; unwrapEnvelope?: UE },
): MonospaceClient<Schema, { unwrapEnvelope: UE; strictNull: SN }> {
	return _createClient<Schema, { unwrapEnvelope: UE; strictNull: SN }>(config);
}

